  { id: "nexus-cut", name: "Nexus Cut", dev: "Nexus Tools", icon: "img:nexus-cut-icon", color: ["#7c5cff","#ff4d8d"], cat: "Video", type: "web", link: TOOLS_URL.replace("tools.html","nexuscut.html"), apk: "#", version: "1.0.0", size: "< 1 MB", rating: 0, downloads: 0, updated: "2026-11-19", featured: true, price: 0, badge: "new", desc: "Pro video editor: timeline, stickers, overlays, voice, effects", long: "Edit videos right on your phone. Add many videos and photos, trim, split and reorder them on a timeline, change speed and volume, fix colours (brightness, contrast, warmth, vignette), zoom, rotate and flip, add filters, effects and smooth transitions. Put stickers and small overlay videos on top, add animated text and subtitles from your script, record your own voice-over, add music, and export in 480p, 720p or 1080p at 24, 30 or 60 frames per second. Undo and redo are always there. Your files never leave your phone.", whatsnew: "Undo and redo, colour adjust, position and rotate, stickers, overlay video, voice-over, subtitles and 1080p export.", perms: ["Reads the videos, photos and music you choose", "Nothing is uploaded"], video: "", screenshots: ["img:nexus-cut-1", "img:nexus-cut-2", "img:nexus-cut-3", "img:nexus-cut-4"] }
